#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmp_str(const void *a, const void *b) {
    return strcmp((const char *)a, (const char *)b);
}

int find_freq(const char *key, char unique[][12], int *freq, int m) {
    int lo = 0, hi = m - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int c = strcmp(key, unique[mid]);
        if (c == 0) return freq[mid];
        if (c < 0) hi = mid - 1;
        else lo = mid + 1;
    }
    return 0;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char s[20000][12];
    for (int i = 0; i < N; i++) {
        scanf("%s", s[i]);
    }

    qsort(s, N, sizeof(s[0]), cmp_str);

    char unique[20000][12];
    int freq[20000];
    int m = 0;

    for (int i = 0; i < N; i++) {
        if (i == 0 || strcmp(s[i], s[i - 1]) != 0) {
            strcpy(unique[m], s[i]);
            freq[m] = 1;
            m++;
        } else {
            freq[m - 1]++;
        }
    }

    long long ans = 0;

    for (int i = 0; i < N; i++) {
        char subs[55][12];
        int cnt = 0;
        int len = strlen(s[i]);

        for (int start = 0; start < len; start++) {
            for (int l = 1; start + l <= len; l++) {
                strncpy(subs[cnt], s[i] + start, l);
                subs[cnt][l] = '\0';
                cnt++;
            }
        }

        qsort(subs, cnt, sizeof(subs[0]), cmp_str);

        for (int j = 0; j < cnt; j++) {
            if (j == 0 || strcmp(subs[j], subs[j - 1]) != 0) {
                ans += find_freq(subs[j], unique, freq, m);
            }
        }

        ans -= 1;
    }

    printf("%lld\n", ans);
    return 0;
}
