#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static int cmp_u64(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static inline uint64_t val(char c) {
    if (c >= '0' && c <= '9') return (uint64_t)(c - '0' + 1);
    return (uint64_t)(c - 'a' + 11);
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    uint64_t *subs = (uint64_t *)malloc((size_t)N * 55 * sizeof(uint64_t));
    uint64_t *pass = (uint64_t *)malloc((size_t)N * sizeof(uint64_t));
    if (!subs || !pass) return 1;

    char s[12];
    int sub_count = 0;

    for (int i = 0; i < N; i++) {
        scanf("%s", s);
        int L = (int)strlen(s);

        uint64_t pcode = 0;
        for (int j = 0; j < L; j++) {
            pcode = pcode * 37 + val(s[j]);
        }
        pass[i] = pcode;

        uint64_t local[55];
        int lc = 0;

        for (int j = 0; j < L; j++) {
            uint64_t code = 0;
            for (int k = j; k < L; k++) {
                code = code * 37 + val(s[k]);

                int found = 0;
                for (int t = 0; t < lc; t++) {
                    if (local[t] == code) {
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    local[lc++] = code;
                }
            }
        }

        for (int t = 0; t < lc; t++) {
            subs[sub_count++] = local[t];
        }
    }

    qsort(subs, sub_count, sizeof(uint64_t), cmp_u64);
    qsort(pass, N, sizeof(uint64_t), cmp_u64);

    long long ans = 0;

    int i = 0;
    while (i < N) {
        uint64_t code = pass[i];
        int c = 1;
        while (i + c < N && pass[i + c] == code) c++;

        int lo = 0, hi = sub_count;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (subs[mid] < code) lo = mid + 1;
            else hi = mid;
        }
        int lb = lo;

        lo = 0, hi = sub_count;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (subs[mid] <= code) lo = mid + 1;
            else hi = mid;
        }
        int ub = lo;

        long long contained = ub - lb;
        ans += (long long)c * (contained - 1);

        i += c;
    }

    printf("%lld\n", ans);

    free(subs);
    free(pass);
    return 0;
}
